// src/lib/translations.ts

import { LOCALE_DATA } from '@/lib/locale-data';
import { LOCALE_CODES, type LocaleCode } from '@/lib/locales';

/**
 * The translation API: `t(key)` strings, keyed by language.
 *
 * WHERE THE STRINGS COME FROM
 *   `LOCALE_DATA` in `src/lib/locale-data.ts` is generated by
 *   `scripts/generate-locales.mjs`. It carries all 18 keys for all 51 languages,
 *   so `Language` below is a union of 51 codes rather than the five that used to
 *   be maintained by hand here.
 *
 * WHY THIS FILE IS STILL SEPARATE FROM THE DATA
 *   Everything that consumes translations imports THIS module, not the generated
 *   one. That keeps the generated file a pure artefact — re-running the
 *   generator cannot change the import path any caller uses, and the loader is a
 *   single place to add a cache or a fallback later.
 *
 * ADDING A LANGUAGE
 *   1. add the code to `LOCALE_CODES` in `src/lib/locales.ts`
 *   2. run `npm run generate:locales`
 *   `Language` widens automatically, and the picker offers it — the type is
 *   derived, so a code without strings cannot be selected. That is deliberate:
 *   it is what stops the picker becoming a list that does nothing.
 */

/**
 * Every language, with every key.
 *
 * The cast is required and is the only one in the module: `LOCALE_DATA` is
 * generated with `as const`, so its inferred type has all 51 keys, but the
 * values are `string`-literal unions rather than the broader `string` this map
 * promises. The shape is otherwise identical, and a missing key in the generated
 * data would be caught by the loader's fallback plus `src/lib/locales.test.ts`.
 */
export const translations = LOCALE_DATA as unknown as Record<
  LocaleCode,
  Record<string, string>
>;

/** Any language the app has strings for. Widens with `LOCALE_CODES`. */
export type Language = LocaleCode;

/** A translatable key. Derived from English, which is the source of truth. */
export type TranslationKey = keyof (typeof LOCALE_DATA)['en'];

/** All languages, in the picker's display order. */
export { LOCALE_CODES };
